), edge_source_checks as (
 select count(*)candidates,count(*)filter(where f.native_id is null or t.native_id is null or f.payload_sha256 is distinct from n.evidence_sha256 or (
 case n.field when 'source_capture_id'then f.data->>'sourceCaptureId'=n.to_id and n.to_type='source-captures'
 when 'reported_service_court_reference'then f.data->>'courtReferenceId'=n.to_id and n.to_type='court-label-references'
 when 'official_court_site_reference'then f.data->>'courtReferenceId'=n.to_id and n.to_type='court-label-references'
 when 'official_MDL_judge_profile_reference'then f.data->>'masterReferenceId'=n.to_id and n.to_type='court-master-references'
 when 'corroborating_conflict_source_capture_ids'then f.data->'sourceCaptureIds'?n.to_id and n.to_type='source-captures'
 else false end)is not true)native_field_mismatches
 from expected_edges n left join private_expected f on f.entity_type=n.from_type and f.native_id=n.from_id
 left join private_expected t on t.entity_type=n.to_type and t.native_id=n.to_id
), actual_edges as materialized (
 select source_system,from_type,from_id,field,to_type,to_id,evidence_sha256,inferred,target_present,run_id from corpus_ingest.relationships where source_system='jpml-html'and run_id='9618c42d-d746-40f1-af56-2d5e4a0fa46f'::uuid
), edge_differences as (
 select count(*)filter(where e.from_id is null)unexpected,count(*)filter(where a.from_id is null)missing,
 count(*)filter(where e.from_id is not null and a.from_id is not null and to_jsonb(e)is distinct from to_jsonb(a))mismatched,
 (select count(*)from actual_edges where inferred)source_inferred_edges
 from expected_edges e full join actual_edges a using(source_system,from_type,from_id,field,to_type,to_id,evidence_sha256)
), base_guard as (
 select (s.expected_records=96 and s.held_records=3 and s.source_mismatches=0 and s.run_observations=96 and s.captured_sources=7 and s.source_text_mismatches=0 and s.rejected_capture_mismatches=0
 and c.mismatches=0 and e.candidates=102 and e.native_field_mismatches=0)ok
 from source_checks s cross join capture_checks c cross join edge_source_checks e
), safe_records as materialized (
 select p.*,p.data-array['text','privateRawLocator'] safe_data,
 'jpml-html:'||entity_type||':'||native_id public_id,
 row_number()over(order by entity_type collate "C",native_id collate "C") public_ordinal,
 case entity_type
 when 'mdl-motion-observations'then 'July 2026 motion index — MDL '||(data->>'mdlNumber')||' · '||(data->>'captionAsReported')
 when 'court-master-references'then 'Court master reference — MDL '||(data->>'mdlNumber')||' · '||(data->>'captionAsReported')
 when 'order-locators'then 'Unread order locator — MDL '||(data->>'mdlNumber')||' · '||(data->>'anchorLabelAsReported')
 when 'source-caption-conflicts'then 'Caption conflict audit — MDL '||(data->>'mdlNumber')
 when 'dated-report-locators'then(data->>'reportLabel')||' · '||(data->>'reportDateLabelAsReported')
 when 'statistics-report-locators'then(data->>'reportLabelAsReported')||' · report locator'
 when 'panel-memberships'then(data->>'nameAsReported')||' · JPML '||(data->>'panelRoleAsReported')
 when 'court-label-references'then data->>'courtLabelAsReported'
 when 'judge-profile-references'then(data->>'nameAsReported')||' · MDL '||(data->>'mdlNumber')||' court-page reference'
 when 'source-captures'then case native_id when 'jpml-pending-mdls-20261002'then'JPML pending and terminated report locator page'
 when 'jpml-panel-orders-20261002'then'JPML July 2026 panel-order index'
 when 'jpml-statistics-20261002'then'JPML statistics directory — first page'
 when 'jpml-about-panel-20261002'then'JPML panel-membership information'
 when 'mnd-change-healthcare-3108-20261002'then'District of Minnesota — MDL 3108 information'
 when 'cand-social-media-current-3047-20261002'then'Northern District of California — MDL 3047 case information'
 when 'cand-ygr-judge-20261002'then'Northern District of California — Judge Gonzalez Rogers profile'end
 end display_title,
 coalesce(data->>'recordScope',data->>'statusScope',data->>'referenceScope',data->>'directoryScope',case when entity_type='source-caption-conflicts'then'Conflicting source labels; automatic overwrite prohibited'else'Dated official HTML metadata; document bodies not acquired'end)display_scope,
 jsonb_build_array(jsonb_build_object('url',source_url,'label','Captured official HTML source'))
 ||case when nullif(data->>'profileUrl','')is not null then jsonb_build_array(jsonb_build_object('url',data->>'profileUrl','label','Explicit official judge profile'))else'[]'::jsonb end
 ||case when nullif(data->>'documentUrl','')is not null then jsonb_build_array(jsonb_build_object('url',data->>'documentUrl','label','PDF locator — body not acquired'))else'[]'::jsonb end public_links
 from private_expected p where not held
), public_expected as materialized (
 select 'jpml_html_reference'::text dataset,public_id id,'jpml_html_reference'::text category,null::text state,display_title title,source_url,public_ordinal ordinal,
 jsonb_build_object('id',public_id,'title',display_title,'subtitle',display_scope,
 'cells',jsonb_build_object('native_id',native_id,'kind',entity_type,'mdl_number',data->>'mdlNumber','court',coalesce(data->>'courtAsReported',data->>'courtLabelAsReported',data->>'serviceCourtAsReported'),'judge',data->>'nameAsReported','report_date',coalesce(data->>'reportDateLabelAsReported',data->>'sessionAsReported'),'scope',display_scope),
 'links',public_links,'badges',jsonb_build_array(case when entity_type='panel-memberships'then'Panel membership; not MDL assignment'when entity_type='source-caption-conflicts'then'Conflict retained; no automatic mapping'when entity_type in('order-locators','dated-report-locators','statistics-report-locators')then'Locator only; body unread'when entity_type='mdl-motion-observations'then'July-session observation only'else'Dated court-source reference'end))item,
 jsonb_build_object('id',public_id,'title',display_title,'subtitle',display_scope,
 'facts',jsonb_build_array(jsonb_build_array('Evidence kind',entity_type),jsonb_build_array('MDL number',data->>'mdlNumber'),jsonb_build_array('Case number as reported',data->>'districtCaseNumberAsReported'),jsonb_build_array('Court as reported',coalesce(data->>'courtAsReported',data->>'courtLabelAsReported',data->>'serviceCourtAsReported')),jsonb_build_array('Judge as reported',data->>'nameAsReported'),jsonb_build_array('Source session',data->>'sessionAsReported'),jsonb_build_array('Report scope/date',data->>'reportDateLabelAsReported'),jsonb_build_array('Displayed last-filing date',data->>'lastFilingDateDisplayed'),jsonb_build_array('Last-filing date qualification',data->>'lastFilingDateQualification'),jsonb_build_array('Capture day',data->>'captureDate')),
 'links',public_links,'qualification',data->>'qualification','source_metadata',safe_data,
 'provenance',jsonb_build_object('source_system','jpml-html','schema_version',schema_version,'native_id',native_id,'record_sha256',payload_sha256,'source_sha256',source_sha256,'source_text_sha256',data->>'sourceTextSha256','retrieved_at',provenance->>'retrieved_at','hash_kind',provenance->>'hash_kind','retrieval_timestamp_qualification',provenance->>'retrieval_timestamp_qualification'))detail,
 jsonb_pretty(safe_data)text,
 jsonb_build_object('_listing','true','native_id',native_id,'kind',entity_type,'mdl_number',data->>'mdlNumber','source_capture_id',data->>'sourceCaptureId','capture_date','2026-10-02','evidence_version','jpml-html-reference/1')filters,array[]::text[]county_geoids
 from safe_records
), facet_names(name,label,ordinal)as(values('kind'::text,'Evidence kind'::text,1),('mdl_number'::text,'MDL number'::text,2),('source_capture_id'::text,'Captured source'::text,3)),
 expected_options as materialized (
 select f.name,p.filters->>f.name value,count(*)n from public_expected p cross join facet_names f where nullif(p.filters->>f.name,'')is not null group by f.name,p.filters->>f.name
), expected_facets as (
 select jsonb_agg(jsonb_build_object('name',f.name,'type','select','label',f.label,'options',v.options)order by f.ordinal)filters
 from facet_names f join lateral(select jsonb_agg(jsonb_build_object('value',value,'label',replace(value,'-',' '),'count',o.n)order by value collate "C")options from expected_options o where o.name=f.name)v on true
)
, written as (
 insert into corpus_ingest.relationships(source_system,from_type,from_id,field,to_type,to_id,evidence_sha256,inferred,target_present,run_id)
 select n.* from expected_edges n where(select ok from base_guard)
 on conflict do nothing returning from_id
)
select jsonb_build_object('base_guard',(select ok from base_guard),'native_edge_candidates',(select candidates from edge_source_checks),'native_field_mismatches',(select native_field_mismatches from edge_source_checks),'edges_written',(select count(*)from written),'expected_inferred_edges',0,'run_id','9618c42d-d746-40f1-af56-2d5e4a0fa46f')receipt;

