), private_expected as materialized (
 select f.*,e.data,e.provenance,e.review_status,e.schema_version,e.payload_sha256 current_payload_sha256,
 v.data version_data,v.schema_version version_schema,
 exists(select 1 from corpus_ingest.observations o where o.run_id='9618c42d-d746-40f1-af56-2d5e4a0fa46f'::uuid and o.source_system='jpml-html' and o.entity_type=f.entity_type and o.native_id=f.native_id and o.payload_sha256=f.payload_sha256 and o.source_url=f.source_url and o.source_sha256=f.source_sha256 and o.retrieved_at=f.retrieved_at and o.source_as_of is null and o.provenance->>'record_sha256'=f.payload_sha256 and o.provenance->>'hash_kind'=f.hash_kind and o.provenance->>'retrieval_timestamp_qualification'=f.retrieval_timestamp_qualification) observation_present
 from fingerprints f left join corpus_ingest.entities e on e.source_system='jpml-html' and e.entity_type=f.entity_type and e.native_id=f.native_id
