 when 'official_court_site_reference'then f.data->>'courtReferenceId'=n.to_id and n.to_type='court-label-references'
 when 'official_MDL_judge_profile_reference'then f.data->>'masterReferenceId'=n.to_id and n.to_type='court-master-references'
 when 'corroborating_conflict_source_capture_ids'then f.data->'sourceCaptureIds'?n.to_id and n.to_type='source-captures'
 else false end)is not true)native_field_mismatches
 from expected_edges n left join private_expected f on f.entity_type=n.from_type and f.native_id=n.from_id
 left join private_expected t on t.entity_type=n.to_type and t.native_id=n.to_id
), actual_edges as materialized (
 select source_system,from_type,from_id,field,to_type,to_id,evidence_sha256,inferred,target_present,run_id from corpus_ingest.relationships where source_system='jpml-html'and run_id='9618c42d-d746-40f1-af56-2d5e4a0fa46f'::uuid
), edge_differences as (
 select count(*)filter(where e.from_id is null)unexpected,count(*)filter(where a.from_id is null)missing,
 count(*)filter(where e.from_id is not null and a.from_id is not null and to_jsonb(e)is distinct from to_jsonb(a))mismatched,
