 when 'mdl-motion-observations'then 'July 2026 motion index — MDL '||(data->>'mdlNumber')||' · '||(data->>'captionAsReported')
 when 'court-master-references'then 'Court master reference — MDL '||(data->>'mdlNumber')||' · '||(data->>'captionAsReported')
