 when 'judge-profile-references'then(data->>'nameAsReported')||' · MDL '||(data->>'mdlNumber')||' court-page reference'
 when 'source-captures'then case native_id when 'jpml-pending-mdls-20261002'then'JPML pending and terminated report locator page'
 when 'jpml-panel-orders-20261002'then'JPML July 2026 panel-order index'
 when 'jpml-statistics-20261002'then'JPML statistics directory — first page'
 when 'jpml-about-panel-20261002'then'JPML panel-membership information'
 when 'mnd-change-healthcare-3108-20261002'then'District of Minnesota — MDL 3108 information'
 when 'cand-social-media-current-3047-20261002'then'Northern District of California — MDL 3047 case information'
 when 'cand-ygr-judge-20261002'then'Northern District of California — Judge Gonzalez Rogers profile'end
 end display_title,
 coalesce(data->>'recordScope',data->>'statusScope',data->>'referenceScope',data->>'directoryScope',case when entity_type='source-caption-conflicts'then'Conflicting source labels; automatic overwrite prohibited'else'Dated official HTML metadata; document bodies not acquired'end)display_scope,
 jsonb_build_array(jsonb_build_object('url',source_url,'label','Captured official HTML source'))
 ||case when nullif(data->>'profileUrl','')is not null then jsonb_build_array(jsonb_build_object('url',data->>'profileUrl','label','Explicit official judge profile'))else'[]'::jsonb end
 ||case when nullif(data->>'documentUrl','')is not null then jsonb_build_array(jsonb_build_object('url',data->>'documentUrl','label','PDF locator — body not acquired'))else'[]'::jsonb end public_links
