 'links',public_links,'badges',jsonb_build_array(case when entity_type='panel-memberships'then'Panel membership; not MDL assignment'when entity_type='source-caption-conflicts'then'Conflict retained; no automatic mapping'when entity_type in('order-locators','dated-report-locators','statistics-report-locators')then'Locator only; body unread'when entity_type='mdl-motion-observations'then'July-session observation only'else'Dated court-source reference'end))item,
 jsonb_build_object('id',public_id,'title',display_title,'subtitle',display_scope,
 'facts',jsonb_build_array(jsonb_build_array('Evidence kind',entity_type),jsonb_build_array('MDL number',data->>'mdlNumber'),jsonb_build_array('Case number as reported',data->>'districtCaseNumberAsReported'),jsonb_build_array('Court as reported',coalesce(data->>'courtAsReported',data->>'courtLabelAsReported',data->>'serviceCourtAsReported')),jsonb_build_array('Judge as reported',data->>'nameAsReported'),jsonb_build_array('Source session',data->>'sessionAsReported'),jsonb_build_array('Report scope/date',data->>'reportDateLabelAsReported'),jsonb_build_array('Displayed last-filing date',data->>'lastFilingDateDisplayed'),jsonb_build_array('Last-filing date qualification',data->>'lastFilingDateQualification'),jsonb_build_array('Capture day',data->>'captureDate')),
 'links',public_links,'qualification',data->>'qualification','source_metadata',safe_data,
 'provenance',jsonb_build_object('source_system','jpml-html','schema_version',schema_version,'native_id',native_id,'record_sha256',payload_sha256,'source_sha256',source_sha256,'source_text_sha256',data->>'sourceTextSha256','retrieved_at',provenance->>'retrieved_at','hash_kind',provenance->>'hash_kind','retrieval_timestamp_qualification',provenance->>'retrieval_timestamp_qualification'))detail,
 jsonb_pretty(safe_data)text,
