), source_checks as materialized (
 select count(*)expected_records,count(*)filter(where held)held_records,
 count(*)filter(where data is null or version_data is null or data is distinct from version_data or schema_version is distinct from '1.0.0' or version_schema is distinct from '1.0.0'
 or (review_status='quarantined' and not held) or current_payload_sha256 is distinct from payload_sha256 or corpus_ingest.canonical_integer_jsonb_sha256_v1(data) is distinct from payload_sha256 or not observation_present
 or provenance->>'source_url' is distinct from source_url or provenance->>'source_sha256' is distinct from source_sha256 or (provenance->>'retrieved_at')::timestamptz is distinct from retrieved_at
