select jsonb_build_object('publication',(select to_jsonb(p)from published p),'source_checks',(select to_jsonb(s)from source_checks s),'source_capture_checks',(select to_jsonb(c)from capture_checks c),'edge_native_field_checks',(select to_jsonb(e)from edge_source_checks e),'edge_differences',(select to_jsonb(e)from edge_differences e),'public_fullfield_differences',(select to_jsonb(d)from differences d),'facet_definition_checks',(select to_jsonb(f)from facet_definition_checks f),'facet_option_mismatches',(select mismatches from facet_option_checks),'hold_checks',(select to_jsonb(h)from hold_checks h),'safety_checks',(select to_jsonb(s)from safety_checks s))receipt;

